package com.remzone.blink.tv;

import android.app.Activity;
import android.net.*;
import android.os.*;
import android.widget.*;
import java.util.concurrent.*;

/** Each probe binds to the explicitly chosen network; failures never switch paths. */
public final class DiagnosticsActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());
    private TextView direct,tunnel,google,youtube;private boolean busy;private Button ownButton,vpnButton,googleButton,youtubeButton;
    private String directResult="Ещё не проверен",tunnelResult="Ещё не проверен";
    @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout page=BlinkStyle.page(this,"Как чувствует себя сеть?","Проверь маршрут. Убедись, что всё на связи.");
        LinearLayout[] ips=pair(page,"Мой IP","IP туннеля");direct=BlinkStyle.text(this,"Твоя обычная сеть. Проверим по нажатию.",16,BlinkStyle.MUTED);ips[0].addView(direct);ownButton=BlinkStyle.button(this,ips[0],"Проверить мой IP",()->probe(false,"www.cloudflare.com","/cdn-cgi/trace",true,direct));tunnel=BlinkStyle.text(this,"Адрес выхода выбранного сервера.",16,BlinkStyle.MUTED);ips[1].addView(tunnel);vpnButton=BlinkStyle.button(this,ips[1],"Проверить IP туннеля",()->probe(true,"www.cloudflare.com","/cdn-cgi/trace",true,tunnel));
        LinearLayout[] checks=pair(page,"Google","YouTube");google=BlinkStyle.text(this,"Как быстро отвечает сервис?",16,BlinkStyle.MUTED);checks[0].addView(google);googleButton=BlinkStyle.button(this,checks[0],"Google · HTTPS-пинг",()->probe(true,"www.google.com","/generate_204",false,google));youtube=BlinkStyle.text(this,"Проверим доступ через твой туннель.",16,BlinkStyle.MUTED);checks[1].addView(youtube);youtubeButton=BlinkStyle.button(this,checks[1],"Проверить YouTube",()->probe(true,"www.youtube.com","/generate_204",false,youtube));
        page.addView(BlinkStyle.text(this,"Мой IP проверяется напрямую по твоему нажатию. Остальные проверки идут через активный VPN. HTTPS-пинг — не ICMP и не замер скорости видео.",12,BlinkStyle.MUTED));BlinkStyle.button(this,page,"Назад",this::finish);
    }
    private LinearLayout[] pair(LinearLayout page,String first,String second){boolean wide=DeviceLayout.twoColumns(getResources().getConfiguration());LinearLayout row=new LinearLayout(this);row.setOrientation(wide?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);row.setClipChildren(false);page.addView(row);LinearLayout left=BlinkStyle.card(this,row,first),right=BlinkStyle.card(this,row,second);if(wide){LinearLayout.LayoutParams l=(LinearLayout.LayoutParams)left.getLayoutParams();l.width=0;l.weight=1;l.rightMargin=BlinkStyle.dp(this,16);left.setLayoutParams(l);LinearLayout.LayoutParams r=(LinearLayout.LayoutParams)right.getLayoutParams();r.width=0;r.weight=1;right.setLayoutParams(r);}return new LinearLayout[]{left,right};}
    private Network network(boolean vpn)throws Exception{ConnectivityManager cm=getSystemService(ConnectivityManager.class);if(vpn){Network n=cm.getActiveNetwork();NetworkCapabilities c=cm.getNetworkCapabilities(n);if(n==null||c==null||!c.hasTransport(NetworkCapabilities.TRANSPORT_VPN)||!"ready".equals(StateStore.state))throw new Exception();return n;}for(Network n:cm.getAllNetworks()){NetworkCapabilities c=cm.getNetworkCapabilities(n);if(c!=null&&!c.hasTransport(NetworkCapabilities.TRANSPORT_VPN)&&c.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)&&(c.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)||c.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)))return n;}throw new Exception();}
    private void probe(boolean vpn,String host,String path,boolean wantIP,TextView target){if(busy)return;busy=true;enabled(false);target.setText("Проверяем "+(vpn?"туннель":"обычную сеть")+"…");worker.execute(()->{String message;try{Network selected=network(vpn);NetworkProbe.Result r=NetworkProbe.measure(selected,host,path,wantIP,!vpn);if(!selected.equals(network(vpn)))throw new Exception();String now=java.text.DateFormat.getTimeInstance(java.text.DateFormat.SHORT).format(new java.util.Date());message=(wantIP?r.ip:host+" · доступен")+" · "+r.totalMs+" мс · "+now+"\n"+r.summary();if(wantIP){if(vpn)tunnelResult=message;else directResult=message;}}catch(Exception e){message=(vpn?"Туннель":"Обычная сеть")+": проверка не прошла"+(e instanceof NetworkProbe.Failure?"\n"+((NetworkProbe.Failure)e).summary():". Проверьте подключение.");}String result=message;main.post(()->{busy=false;if(isDestroyed())return;target.setText(result);BlinkStyle.reveal(target);enabled(true);});});}
    private void enabled(boolean enabled){ownButton.setEnabled(enabled);vpnButton.setEnabled(enabled);googleButton.setEnabled(enabled);youtubeButton.setEnabled(enabled);}
    @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
